int *twoSum(int *nums, int numsSize, int target, int *returnSize)
{
    int i, j;
    int *ret = calloc(2, sizeof(int));
    for (i = 0; i < numsSize; i++)
    {
        int key = target - nums[i];
        for (j = i + 1; j < numsSize; j++)
            if (nums[j] == key)
            {
                ret[0] = i;
                ret[1] = j;
            }
    }
    *returnSize = 2;
    return ret;
}

/*
Prompt:

Given an input string s and a pattern p, implement regular expression matching with support for '.' and '*' where:
- '.' Matches any single character.
- '*' Matches zero or more of the preceding element.
The matching should cover the entire input string (not partial).

Constraints:

1 <= s.length <= 20
1 <= p.length <= 30
s contains only lowercase English letters.
p contains only lowercase English letters, '.', and '*'.

It is guaranteed for each appearance of the character '*', there will be a previous valid character to match.
*/

bool isMatch(char* s, char* p);
bool matchStar(char ch, char* s, char* p);

/*
Uses Rob pikes Regexp matcher - https://www.cs.princeton.edu/courses/archive/spr09/cos333/beautiful.html
Implementation:
    // match: search for regexp anywhere in text 
    int match(char *regexp, char *text)
    {
        if (regexp[0] == '^')
            return matchhere(regexp+1, text);
        do {  
            if (matchhere(regexp, text))
                return 1;
        } while (*text++ != '\0');
        return 0;
    }
*/

bool matchStar(char ch, char* s, char* p) {
  do {
    if (isMatch(s, p))
      return true;
  } while (*s != '\0' && (*s++ == ch || ch == '.'));

  return false;
}

bool isMatch(char* s, char* p) {
  if (*p == '\0')
    return *s == '\0';

  if (p[1] == '*')
    return matchStar(p[0], s, p + 2);

  if (*s != '\0' && (p[0] == '.' || *p == *s)) {
    return isMatch(s + 1, p + 1);
  }

  return false;
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */

struct TreeNode* bstFromPreorder(int* preorder, int preorderSize)
{
    struct TreeNode* new;
    int left_ptr;

    new = malloc(sizeof(struct TreeNode));
    new->val = preorder[0];

    if (preorderSize == 1)
    {
        new->right = NULL;
        new->left = NULL;
        return new;
    }

    left_ptr = 1;
    while ((left_ptr < preorderSize) && (preorder[left_ptr] < preorder[0]))
        left_ptr++;
    if (left_ptr == 1)
        new->left = NULL;
    else
        new->left = bstFromPreorder(preorder + 1, left_ptr - 1);
    if (left_ptr < preorderSize)
        new->right =
            bstFromPreorder(preorder + left_ptr, preorderSize - left_ptr);
    else
        new->right = NULL;

    return new;
}

// Bit manipulation.
// - Find the bit length of n using log2
// - Create bit mask of bit length of n
// - Retun ~n and bit of ones mask
// Runtime: O(log2(n))
// Space: O(1)

int bitwiseComplement(int n){
    if (n == 0){
        return 1;
    }

    int binary_number_length = ceil(log2(n));
    return (~n) & ((1 << binary_number_length) - 1);
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */

bool checkSymmetric(struct TreeNode *left, struct TreeNode *right)
{
    if (!left || !right)
        return left == right;
    if (left->val != right->val)
        return 0;
    return checkSymmetric(left->left, right->right) &&
           checkSymmetric(left->right, right->left);
}

bool isSymmetric(struct TreeNode *root)
{
    return root == NULL || checkSymmetric(root->left, root->right);
}

