// Counting whole summ. evens sums number and odd summs number.
// Runtime: O(n),
// Space: O(1)
int numOfSubarrays(int* arr, int arrSize){
    int result = 0;
    int curSumm = 0;
    int currOddSumms = 0;
    int currEvenSumm = 0;
    int modulo = 1000000000 + 7;

    for(int i = 0; i < arrSize; i++){
        curSumm += arr[i];
        if (curSumm % 2 == 0){
            currEvenSumm++;
            result = (result + currOddSumms) % modulo;
        }
        else {
            currOddSumms++;
            result = (result + 1 + currEvenSumm) % modulo;
        }
    }

    return result % modulo;
}

#include <stdlib.h> // for qsort()

int cmp(const void* a, const void* b) {
    const int *A = a, *B = b;
    return (*A > *B) - (*A < *B);
}

int threeSumClosest(int* nums, int nums_size, int target) {
    int i, j, k, result, sum3;
    qsort(nums, nums_size, sizeof(int), cmp);
    result = nums[0] + nums[1] + nums[2];
    for (i = 0; i < nums_size - 2; i++) {
        j = i + 1;
        k = nums_size - 1;
        while (j < k) {
            sum3 = nums[i] + nums[j] + nums[k];
            if (abs(target - sum3) < abs(target - result)) {
                result = sum3;
            }
            if (sum3 < target) {
                j++;
            } else if (sum3 > target) {
                k--;
            } else {
                return sum3;
            }
        }
    }
    return result;
}

struct ListNode *getIntersectionNode(struct ListNode *headA,
                                     struct ListNode *headB)
{
    struct ListNode *cur1 = headA, *cur2 = headB;
    if (cur1 == NULL || cur2 == NULL)
        return NULL;
    while (cur1 && cur2 && cur1 != cur2)
    {
        cur1 = cur1->next;
        cur2 = cur2->next;
        if (cur1 == cur2)
            return cur1;
        if (!cur1)
            cur1 = headB;
        if (!cur2)
            cur2 = headA;
    }
    return cur1;
}

