struct ListNode *removeNthFromEnd(struct ListNode *head, int n) {
    struct ListNode entry, *p_free, *p = head;
    int i, sz = 0;
    entry.next = head;
    while (p != NULL) {
        p = p->next;
        sz++;
    }
    for (i = 0, p = &entry; i < sz - n; i++, p = p -> next)
    ;
    p_free = p->next;
