    int* arr = malloc(count * sizeof(int));
    while (dup != NULL)
    {
        arr[i++] = dup->val;
        dup = dup->next;
    }
    for (i = 0; i < count / 2; ++i)
    {
        if (arr[i] + arr[count - i - 1] > max)
            max = arr[i] + arr[count - i - 1];
    }
    return max;
}

