    char str2[] = "kathrin";

    assert(hamming_distance(str1, str2) == 3);

    char str3[] = "00000";
    char str4[] = "11111";

    assert(hamming_distance(str3, str4) == 5);
    printf("All tests have successfully passed!\n");
}
