    (MAX_DENO + 10) /**< length of resulting recurring fraction number */

/** comparison function for use with internal `qsort` algorithm */
int compare(const void *a, const void *b)
{
    return (*(unsigned short *)a - *(unsigned short *)b);
}

/** Main function */
