/**
 * \file
 * \brief [Problem 3](https://projecteuler.net/problem=3) solution
 *
 * Problem:
 *
 * The prime factors of 13195 are 5,7,13 and 29. What is the largest prime
 * factor of a given number N? e.g. for 10, largest prime factor = 5. For 17,
 * largest prime factor = 17.
 */
#include <math.h>
#include <stdio.h>

/** Check if the given number is prime */
char isprime(int no)
{
    int sq;

    if (no == 2)
    {
        return 1;
    }
    else if (no % 2 == 0)
    {
        return 0;
    }
    sq = ((int)(sqrt(no))) + 1;
    for (int i = 3; i < sq; i += 2)
    {
        if (no % i == 0)
        {
            return 0;
        }
    }
    return 1;
}

/** Main function */
int main()
{
    int maxNumber = 0;
    int n = 0;
    int n1;
    scanf("%d", &n);
    if (isprime(n) == 1)
        printf("%d", n);
    else
    {
        while (n % 2 == 0)
        {
            n = n / 2;
        }
        if (isprime(n) == 1)
        {
            printf("%d\n", n);
        }
        else
        {
            n1 = ((int)(sqrt(n))) + 1;
            for (int i = 3; i < n1; i += 2)
            {
                if (n % i == 0)
                {
                    if (isprime((int)(n / i)) == 1)
                    {
                        maxNumber = n / i;
                        break;
                    }
                    else if (isprime(i) == 1)
                    {
                        maxNumber = i;
                    }
                }
            }
            printf("%d\n", maxNumber);
        }
    }
    return 0;
}

/**
 * \file
 * \brief [Problem 3](https://projecteuler.net/problem=3) solution
 *
 * Problem:
 *
 * The prime factors of 13195 are 5,7,13 and 29. What is the largest prime
 * factor of a given number N? e.g. for 10, largest prime factor = 5. For 17,
 * largest prime factor = 17.
 */
#include <stdio.h>

/** Main function */
int main()
{
    int n = 0;
    scanf("%d", &n);
    int prime = 1;
    int i = 2;
    while (i * i <= n)
    {
        while (n % i == 0)
        {
            prime = i;
            n /= i;
        }
        i += 1;
    }
    if (n > 1)
        prime = n;
    printf("%d\n", prime);
    return 0;
}

/**
 * \file
 * \brief [Problem 4](https://projecteuler.net/problem=4) solution
 */
#include <stdio.h>

/** Check if number is palindromic
 * \param[in] n number to check
 * \returns 1 if palindromic
 * \returns 0 if not palindromic
 */
int is_palindromic(unsigned int n)
{
    unsigned int reversed = 0, t = n;

    while (t > 0)
    {
        reversed = 10 * reversed + (t % 10);
        t /= 10;
    }
    return reversed == n;
}

/** Main function */
int main(void)
{
    unsigned int i, j, max = 0;
    for (i = 100; i <= 999; i++)
    {
        for (j = 100; j <= 999; j++)
        {
            unsigned int p = i * j;
            if (is_palindromic(p) && p > max)
            {
                max = p;
            }
        }
    }
    printf("%u\n", max);
    return 0;
}

