using Algorithms.Problems.KnightTour;

namespace Algorithms.Tests.Problems.KnightTour
{
    [TestFixture]
    public sealed class OpenKnightTourTests
    {
        private static bool IsKnightMove((int r, int c) a, (int r, int c) b)
        {
            var dr = Math.Abs(a.r - b.r);
            var dc = Math.Abs(a.c - b.c);
            return (dr == 1 && dc == 2) || (dr == 2 && dc == 1);
        }

        private static Dictionary<int, (int r, int c)> MapVisitOrder(int[,] board)
        {
            var n = board.GetLength(0);
            var map = new Dictionary<int, (int r, int c)>(n * n);
            for (var r = 0; r < n; r++)
            {
                for (var c = 0; c < n; c++)
                {
                    var v = board[r, c];
                    if (v <= 0)
                    {
                        continue;
                    }
                    // ignore zeros in partial/invalid boards
                    if (!map.TryAdd(v, (r, c)))
                    {
                        throw new AssertionException($"Duplicate visit number detected: {v}.");
                    }
                }
            }
            return map;
        }

        private static void AssertIsValidTour(int[,] board)
        {
            var n = board.GetLength(0);
            Assert.That(board.GetLength(1), Is.EqualTo(n), "Board must be square.");

            // 1) All cells visited and within [1..n*n]
            int min = int.MaxValue;
            int max = int.MinValue;

            var seen = new bool[n * n + 1]; // 1..n*n
            for (var r = 0; r < n; r++)
            {
                for (var c = 0; c < n; c++)
                {
                    var v = board[r, c];
                    Assert.That(v, Is.InRange(1, n * n),
                        $"Cell [{r},{c}] has out-of-range value {v}.");
                    Assert.That(seen[v], Is.False, $"Duplicate value {v} found.");
                    seen[v] = true;
                    if (v < min)
                    {
                        min = v;
                    }

                    if (v > max)
                    {
                        max = v;
                    }
                }
            }
            Assert.That(min, Is.EqualTo(1), "Tour must start at 1.");
            Assert.That(max, Is.EqualTo(n * n), "Tour must end at n*n.");

            // 2) Each successive step is a legal knight move
            var pos = MapVisitOrder(board); // throws if duplicates
            for (var step = 1; step < n * n; step++)
            {
                var a = pos[step];
                var b = pos[step + 1];
                Assert.That(IsKnightMove(a, b),
                    $"Step {step}->{step + 1} is not a legal knight move: {a} -> {b}.");
            }
        }

        [Test]
        public void Tour_Throws_On_NonPositiveN()
        {
            var solver = new OpenKnightTour();

            Assert.Throws<ArgumentException>(() => solver.Tour(0));
            Assert.Throws<ArgumentException>(() => solver.Tour(-1));
            Assert.Throws<ArgumentException>(() => solver.Tour(-5));
        }

        [TestCase(2)]
        [TestCase(3)]
        [TestCase(4)]
        public void Tour_Throws_On_Unsolvable_N_2_3_4(int n)
        {
            var solver = new OpenKnightTour();
            Assert.Throws<ArgumentException>(() => solver.Tour(n));
        }

        [Test]
        public void Tour_Returns_Valid_1x1()
        {
            var solver = new OpenKnightTour();
            var board = solver.Tour(1);

            Assert.That(board.GetLength(0), Is.EqualTo(1));
            Assert.That(board.GetLength(1), Is.EqualTo(1));
            Assert.That(board[0, 0], Is.EqualTo(1));
            AssertIsValidTour(board);
        }

        /// <summary>
        /// The plain backtracking search can take some time on 5x5 depending on move ordering,
        /// but should still be manageable. We mark it as "Slow" and add a generous timeout.
        /// </summary>
        [Test, Category("Slow"), CancelAfterAttribute(30000)]
        public void Tour_Returns_Valid_5x5()
        {
            var solver = new OpenKnightTour();
            var board = solver.Tour(5);

            // Shape checks
            Assert.That(board.GetLength(0), Is.EqualTo(5));
            Assert.That(board.GetLength(1), Is.EqualTo(5));

            // Structural validity checks
            AssertIsValidTour(board);
        }

        [Test]
        public void Tour_Fills_All_Cells_No_Zeros_On_Successful_Boards()
        {
            var solver = new OpenKnightTour();
            var board = solver.Tour(5);

            for (var r = 0; r < board.GetLength(0); r++)
            {
                for (var c = 0; c < board.GetLength(1); c++)
                {
                    Assert.That(board[r, c], Is.Not.EqualTo(0),
                        $"Found unvisited cell at [{r},{c}].");
                }
            }
        }

        [Test]
        public void Tour_Produces_Values_In_Valid_Range_And_Unique()
        {
            var solver = new OpenKnightTour();
            var n = 5;
            var board = solver.Tour(n);

            var values = new List<int>(n * n);
            for (var r = 0; r < n; r++)
            {
                for (var c = 0; c < n; c++)
                {
                    values.Add(board[r, c]);
                }
            }

            values.Sort();
            // Expect [1..n*n]
            var expected = Enumerable.Range(1, n * n).ToArray();
            Assert.That(values, Is.EqualTo(expected),
                "Board must contain each number exactly once from 1 to n*n.");
        }

        [Test]
        public void Tour_Returns_Square_Array()
        {
            var solver = new OpenKnightTour();
            var board = solver.Tour(5);

            Assert.That(board.GetLength(0), Is.EqualTo(board.GetLength(1)));
        }
    }
}

using Algorithms.Problems.NQueens;

namespace Algorithms.Tests.Problems.NQueens;

public static class BacktrackingNQueensSolverTests
{
    [TestCase(0, 0)]
    [TestCase(1, 1)]
    [TestCase(2, 0)]
    [TestCase(3, 0)]
    [TestCase(4, 2)]
    [TestCase(5, 10)]
    [TestCase(6, 4)]
    [TestCase(7, 40)]
    [TestCase(8, 92)]
    [TestCase(8, 92)]
    [TestCase(9, 352)]
    [TestCase(10, 724)]
    [TestCase(11, 2680)]
    public static void SolvesCorrectly(int n, int expectedNumberOfSolutions)
    {
        // Arrange
        // Act
        var result = new BacktrackingNQueensSolver().BacktrackSolve(n).ToList();

        // Assert
        result.Should().HaveCount(expectedNumberOfSolutions);
        foreach (var solution in result)
        {
            ValidateOneQueenPerRow(solution);
            ValidateOneQueenPerColumn(solution);
            ValidateOneQueenPerTopLeftBottomRightDiagonalLine(solution);
            ValidateOneQueenPerBottomLeftTopRightDiagonalLine(solution);
        }
    }

    [Test]
    public static void NCannotBeNegative()
    {
        var n = -1;

        Action act = () => new BacktrackingNQueensSolver().BacktrackSolve(n);

        act.Should().Throw<ArgumentException>();
    }

    private static void ValidateOneQueenPerRow(bool[,] solution)
    {
        for (var i = 0; i < solution.GetLength(1); i++)
        {
            var foundQueen = false;
            for (var j = 0; j < solution.GetLength(0); j++)
            {
                foundQueen = ValidateCell(foundQueen, solution[j, i]);
            }
        }
    }

    private static void ValidateOneQueenPerColumn(bool[,] solution)
    {
        for (var i = 0; i < solution.GetLength(0); i++)
        {
            var foundQueen = false;
            for (var j = 0; j < solution.GetLength(1); j++)
            {
                foundQueen = ValidateCell(foundQueen, solution[i, j]);
            }
        }
    }

    private static void ValidateOneQueenPerTopLeftBottomRightDiagonalLine(bool[,] solution)
    {
        for (var i = 0; i < solution.GetLength(0); i++)
        {
            var foundQueen = false;
            for (var j = 0; i + j < solution.GetLength(1); j++)
            {
                foundQueen = ValidateCell(foundQueen, solution[i + j, i]);
            }
        }

        for (var i = 0; i < solution.GetLength(1); i++)
        {
            var foundQueen = false;
            for (var j = 0; i + j < solution.GetLength(0); j++)
            {
                foundQueen = ValidateCell(foundQueen, solution[j, i + j]);
            }
        }
    }

    private static void ValidateOneQueenPerBottomLeftTopRightDiagonalLine(bool[,] solution)
    {
        for (var i = 0; i < solution.GetLength(0); i++)
        {
            var foundQueen = false;
            for (var j = 0; i - j >= 0; j++)
            {
                foundQueen = ValidateCell(foundQueen, solution[i - j, i]);
            }
        }

        for (var i = 0; i < solution.GetLength(1); i++)
        {
            var foundQueen = false;
            for (var j = 0; i - j >= 0 && solution.GetLength(0) - j > 0; j++)
            {
                foundQueen = ValidateCell(foundQueen, solution[solution.GetLength(0) - j - 1, i - j]);
            }
        }
    }

    private static bool ValidateCell(bool foundQueen, bool currentCell)
    {
        if (foundQueen)
        {
            currentCell.Should().BeFalse();
        }

        return foundQueen || currentCell;
    }
}

using Algorithms.Problems.StableMarriage;

namespace Algorithms.Tests.Problems.StableMarriage;

/// <summary>
///     The stable marriage problem (also stable matching problem or SMP)
///     is the problem of finding a stable matching between two equally sized sets of elements given an ordering of
///     preferences for each element.
/// </summary>
public static class GaleShapleyTests
{
    /// <summary>
    ///     Checks that all parties are engaged and stable.
    /// </summary>
    [Test]
    public static void MatchingIsSuccessful()
    {
        var random = new Random(7);
        var proposers = Enumerable.Range(1, 10).Select(_ => new Proposer()).ToArray();
        var acceptors = Enumerable.Range(1, 10).Select(_ => new Accepter()).ToArray();

        foreach (var proposer in proposers)
        {
            proposer.PreferenceOrder = new LinkedList<Accepter>(acceptors.OrderBy(_ => random.Next()));
        }

        foreach (var acceptor in acceptors)
        {
            acceptor.PreferenceOrder = proposers.OrderBy(_ => random.Next()).ToList();
        }

        GaleShapley.Match(proposers, acceptors);

        Assert.That(acceptors.ToList().TrueForAll(x => x.EngagedTo is not null));
        Assert.That(proposers.ToList().TrueForAll(x => x.EngagedTo is not null));
        Assert.That(AreMatchesStable(proposers, acceptors), Is.True);
    }

    private static bool AreMatchesStable(Proposer[] proposers, Accepter[] accepters) =>
        proposers.ToList().TrueForAll(p =>
            p.EngagedTo is not null
            && Score(p, p.EngagedTo) <= accepters
                .Where(a => a.PrefersOverCurrent(p))
                .Min(a => Score(p, a)));

    private static int Score(Proposer proposer, Accepter accepter) =>
        proposer.PreferenceOrder.ToList().IndexOf(accepter);
}

using Algorithms.Problems.TravelingSalesman;
using NUnit.Framework;

namespace Algorithms.Tests.Problems.TravelingSalesman;

/// <summary>
/// Unit tests for TravelingSalesmanSolver. Covers brute-force and nearest neighbor methods, including edge cases and invalid input.
/// </summary>
[TestFixture]
public class TravelingSalesmanSolverTests
{
    /// <summary>
    /// Tests brute-force TSP solver on a 4-city symmetric distance matrix with known optimal route.
    /// </summary>
    [Test]
    public void SolveBruteForce_KnownOptimalRoute_ReturnsCorrectResult()
    {
        // Distance matrix for 4 cities (symmetric, triangle inequality holds)
        double[,] matrix =
        {
            { 0, 10, 15, 20 },
            { 10, 0, 35, 25 },
            { 15, 35, 0, 30 },
            { 20, 25, 30, 0 }
        };
        var (route, distance) = TravelingSalesmanSolver.SolveBruteForce(matrix);
        // Optimal route: 0 -> 1 -> 3 -> 2 -> 0, total distance = 80
        Assert.That(distance, Is.EqualTo(80));
        Assert.That(route, Is.EquivalentTo(new[] { 0, 1, 3, 2, 0 }));
    }

    /// <summary>
    /// Tests nearest neighbor heuristic on the same matrix. May not be optimal.
    /// </summary>
    [Test]
    public void SolveNearestNeighbor_Heuristic_ReturnsFeasibleRoute()
    {
        double[,] matrix =
        {
            { 0, 10, 15, 20 },
            { 10, 0, 35, 25 },
            { 15, 35, 0, 30 },
            { 20, 25, 30, 0 }
        };
        var (route, distance) = TravelingSalesmanSolver.SolveNearestNeighbor(matrix, 0);
        // Route: 0 -> 1 -> 3 -> 2 -> 0, total distance = 80
        Assert.That(route.Length, Is.EqualTo(5));
        Assert.That(route.First(), Is.EqualTo(0));
        Assert.That(route.Last(), Is.EqualTo(0));
        Assert.That(distance, Is.GreaterThanOrEqualTo(80)); // Heuristic may be optimal or suboptimal
    }

    /// <summary>
