            int shiftable = 1;  // This will not cause a negative result after left shift

            // Act
            int result = GallopingStrategy<int>.BoundLeftShift(shiftable);

            // Assert
            Assert.That(int.MaxValue, Is.EqualTo(result));  // False branch
        }
