    }
}

namespace Algorithms.Other;

/// <summary>
///     Date of Easter calculated with Meeus's Julian algorithm.
///     The algorithm is described in Jean Meeus' <a href="https://archive.org/details/astronomicalalgorithmsjeanmeeus1991/page/n73/mode/2up">Astronomical Algorithms (1991, p. 69)</a>.
/// </summary>
public static class JulianEaster
{
    /// <summary>
    ///     Calculates the date of Easter.
    /// </summary>
    /// <param name="year">Year to calculate the date of Easter.</param>
    /// <returns>Date of Easter as a DateTime.</returns>
    public static DateTime Calculate(int year)
    {
        var a = year % 4;
        var b = year % 7;
        var c = year % 19;
        var d = (19 * c + 15) % 30;
        var e = (2 * a + 4 * b - d + 34) % 7;
        var month = (int)Math.Floor((d + e + 114) / 31M);
        var day = ((d + e + 114) % 31) + 1;

        DateTime easter = new(year, month, day, 00, 00, 00, DateTimeKind.Utc);

        return easter;
    }
}

namespace Algorithms.Other;

/// <summary>
///     Kadane's Algorithm is used to find the maximum sum of a contiguous subarray
///     within a one-dimensional array of numbers. It has a time complexity of O(n).
///     This algorithm is a classic example of dynamic programming.
///     Reference: "Introduction to Algorithms" by Cormen, Leiserson, Rivest, and Stein (CLRS).
/// </summary>
public static class KadanesAlgorithm
{
    /// <summary>
    ///     Finds the maximum sum of a contiguous subarray using Kadane's Algorithm.
    ///     The algorithm works by maintaining two variables:
    ///     - maxSoFar: The maximum sum found so far (global maximum)
    ///     - maxEndingHere: The maximum sum of subarray ending at current position (local maximum)
    ///     At each position, we decide whether to extend the existing subarray or start a new one.
    /// </summary>
    /// <param name="array">The input array of integers.</param>
    /// <returns>The maximum sum of a contiguous subarray.</returns>
    /// <exception cref="ArgumentException">Thrown when the input array is null or empty.</exception>
    /// <example>
    ///     Input: [-2, 1, -3, 4, -1, 2, 1, -5, 4].
    ///     Output: 6 (subarray [4, -1, 2, 1]).
    /// </example>
    public static int FindMaximumSubarraySum(int[] array)
    {
        // Validate input to ensure array is not null or empty
        if (array == null || array.Length == 0)
        {
            throw new ArgumentException("Array cannot be null or empty.", nameof(array));
        }

        // Initialize both variables with the first element
        // maxSoFar tracks the best sum we've seen across all subarrays
        int maxSoFar = array[0];

        // maxEndingHere tracks the best sum ending at the current position
        int maxEndingHere = array[0];

        // Iterate through the array starting from the second element
        for (int i = 1; i < array.Length; i++)
        {
            // Key decision: Either extend the current subarray or start fresh
            // If adding current element to existing sum is worse than the element alone,
            // it's better to start a new subarray from current element
            maxEndingHere = Math.Max(array[i], maxEndingHere + array[i]);

            // Update the global maximum if current subarray sum is better
            maxSoFar = Math.Max(maxSoFar, maxEndingHere);
        }

        return maxSoFar;
    }

    /// <summary>
    ///     Finds the maximum sum of a contiguous subarray and returns the start and end indices.
    ///     This variant tracks the indices of the maximum subarray in addition to the sum.
    ///     Useful when you need to know which elements form the maximum subarray.
    /// </summary>
    /// <param name="array">The input array of integers.</param>
    /// <returns>A tuple containing the maximum sum, start index, and end index.</returns>
    /// <exception cref="ArgumentException">Thrown when the input array is null or empty.</exception>
    /// <example>
    ///     Input: [-2, 1, -3, 4, -1, 2, 1, -5, 4].
    ///     Output: (MaxSum: 6, StartIndex: 3, EndIndex: 6).
    ///     The subarray is [4, -1, 2, 1].
    /// </example>
    public static (int MaxSum, int StartIndex, int EndIndex) FindMaximumSubarrayWithIndices(int[] array)
    {
        // Validate input
        if (array == null || array.Length == 0)
        {
            throw new ArgumentException("Array cannot be null or empty.", nameof(array));
        }

        // Initialize tracking variables
        int maxSoFar = array[0];        // Global maximum sum
        int maxEndingHere = array[0];   // Local maximum sum ending at current position
        int start = 0;                   // Start index of the maximum subarray
        int end = 0;                     // End index of the maximum subarray
        int tempStart = 0;               // Temporary start index for current subarray

        // Process each element starting from index 1
        for (int i = 1; i < array.Length; i++)
        {
            // Decide whether to extend current subarray or start a new one
            if (array[i] > maxEndingHere + array[i])
            {
                // Starting fresh from current element is better
                maxEndingHere = array[i];
                tempStart = i;  // Mark this as potential start of new subarray
            }
            else
            {
                // Extending the current subarray is better
                maxEndingHere = maxEndingHere + array[i];
            }

            // Update global maximum and indices if we found a better subarray
            if (maxEndingHere > maxSoFar)
            {
                maxSoFar = maxEndingHere;
                start = tempStart;  // Commit the start index
                end = i;            // Current position is the end
            }
        }

        return (maxSoFar, start, end);
    }

    /// <summary>
    ///     Finds the maximum sum of a contiguous subarray using Kadane's Algorithm for long integers.
    ///     This overload handles larger numbers that exceed int range (up to 2^63 - 1).
    ///     The algorithm logic is identical to the int version but uses long arithmetic.
    /// </summary>
    /// <param name="array">The input array of long integers.</param>
    /// <returns>The maximum sum of a contiguous subarray.</returns>
    /// <exception cref="ArgumentException">Thrown when the input array is null or empty.</exception>
    /// <example>
    ///     Input: [1000000000L, -500000000L, 1000000000L].
    ///     Output: 1500000000L (entire array).
    /// </example>
    public static long FindMaximumSubarraySum(long[] array)
    {
        // Validate input
        if (array == null || array.Length == 0)
        {
            throw new ArgumentException("Array cannot be null or empty.", nameof(array));
        }

        // Initialize with first element (using long arithmetic)
        long maxSoFar = array[0];
        long maxEndingHere = array[0];

        // Apply Kadane's algorithm with long values
        for (int i = 1; i < array.Length; i++)
        {
            // Decide: extend current subarray or start new one
            maxEndingHere = Math.Max(array[i], maxEndingHere + array[i]);

            // Update global maximum
            maxSoFar = Math.Max(maxSoFar, maxEndingHere);
        }

        return maxSoFar;
    }
}

using SkiaSharp;

namespace Algorithms.Other;

/// <summary>
///     The Koch snowflake is a fractal curve and one of the earliest fractals to
///     have been described. The Koch snowflake can be built up iteratively, in a
///     sequence of stages. The first stage is an equilateral triangle, and each
///     successive stage is formed by adding outward bends to each side of the
///     previous stage, making smaller equilateral triangles.
///     This can be achieved through the following steps for each line:
///     1. divide the line segment into three segments of equal length.
///     2. draw an equilateral triangle that has the middle segment from step 1
///     as its base and points outward.
///     3. remove the line segment that is the base of the triangle from step 2.
///     (description adapted from https://en.wikipedia.org/wiki/Koch_snowflake )
///     (for a more detailed explanation and an implementation in the
///     Processing language, see  https://natureofcode.com/book/chapter-8-fractals/
///     #84-the-koch-curve-and-the-arraylist-technique ).
/// </summary>
public static class KochSnowflake
{
    /// <summary>
    ///     Go through the number of iterations determined by the argument "steps".
    ///     Be careful with high values (above 5) since the time to calculate increases
    ///     exponentially.
    /// </summary>
    /// <param name="initialVectors">
    ///     The vectors composing the shape to which
    ///     the algorithm is applied.
    /// </param>
    /// <param name="steps">The number of iterations.</param>
    /// <returns>The transformed vectors after the iteration-steps.</returns>
    public static List<Vector2> Iterate(List<Vector2> initialVectors, int steps = 5)
    {
        List<Vector2> vectors = initialVectors;
        for (var i = 0; i < steps; i++)
        {
            vectors = IterationStep(vectors);
        }

        return vectors;
    }

    /// <summary>
    ///     Method to render the Koch snowflake to a bitmap. To save the
    ///     bitmap the command 'GetKochSnowflake().Save("KochSnowflake.png")' can be used.
    /// </summary>
    /// <param name="bitmapWidth">The width of the rendered bitmap.</param>
    /// <param name="steps">The number of iterations.</param>
    /// <returns>The bitmap of the rendered Koch snowflake.</returns>
    public static SKBitmap GetKochSnowflake(
        int bitmapWidth = 600,
        int steps = 5)
    {
        if (bitmapWidth <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(bitmapWidth),
                $"{nameof(bitmapWidth)} should be greater than zero");
        }

        var offsetX = bitmapWidth / 10f;
        var offsetY = bitmapWidth / 3.7f;
        var vector1 = new Vector2(offsetX, offsetY);
        var vector2 = new Vector2(bitmapWidth / 2, (float)Math.Sin(Math.PI / 3) * bitmapWidth * 0.8f + offsetY);
        var vector3 = new Vector2(bitmapWidth - offsetX, offsetY);
        List<Vector2> initialVectors = [vector1, vector2, vector3, vector1];
        List<Vector2> vectors = Iterate(initialVectors, steps);
        return GetBitmap(vectors, bitmapWidth, bitmapWidth);
    }

    /// <summary>
    ///     Loops through each pair of adjacent vectors. Each line between two adjacent
    ///     vectors is divided into 4 segments by adding 3 additional vectors in-between
    ///     the original two vectors. The vector in the middle is constructed through a
    ///     60 degree rotation so it is bent outwards.
    /// </summary>
    /// <param name="vectors">
    ///     The vectors composing the shape to which
    ///     the algorithm is applied.
    /// </param>
    /// <returns>The transformed vectors after the iteration-step.</returns>
    private static List<Vector2> IterationStep(List<Vector2> vectors)
    {
        List<Vector2> newVectors = [];
        for (var i = 0; i < vectors.Count - 1; i++)
        {
            var startVector = vectors[i];
            var endVector = vectors[i + 1];
            newVectors.Add(startVector);
            var differenceVector = endVector - startVector;
            newVectors.Add(startVector + differenceVector / 3);
            newVectors.Add(startVector + differenceVector / 3 + Rotate(differenceVector / 3, 60));
            newVectors.Add(startVector + differenceVector * 2 / 3);
        }

        newVectors.Add(vectors[^1]);
        return newVectors;
    }

    /// <summary>
    ///     Standard rotation of a 2D vector with a rotation matrix
    ///     (see https://en.wikipedia.org/wiki/Rotation_matrix ).
    /// </summary>
    /// <param name="vector">The vector to be rotated.</param>
    /// <param name="angleInDegrees">The angle by which to rotate the vector.</param>
    /// <returns>The rotated vector.</returns>
    private static Vector2 Rotate(Vector2 vector, float angleInDegrees)
    {
        var radians = angleInDegrees * (float)Math.PI / 180;
        var ca = (float)Math.Cos(radians);
        var sa = (float)Math.Sin(radians);
        return new Vector2(ca * vector.X - sa * vector.Y, sa * vector.X + ca * vector.Y);
    }

    /// <summary>
    ///     Utility-method to render the Koch snowflake to a bitmap.
    /// </summary>
    /// <param name="vectors">The vectors defining the edges to be rendered.</param>
    /// <param name="bitmapWidth">The width of the rendered bitmap.</param>
    /// <param name="bitmapHeight">The height of the rendered bitmap.</param>
    /// <returns>The bitmap of the rendered edges.</returns>
    private static SKBitmap GetBitmap(
        List<Vector2> vectors,
        int bitmapWidth,
        int bitmapHeight)
    {
        SKBitmap bitmap = new(bitmapWidth, bitmapHeight);
        var canvas = new SKCanvas(bitmap);

        // Set the background white
        var rect = SKRect.Create(0, 0, bitmapWidth, bitmapHeight);

        var paint = new SKPaint
        {
            Style = SKPaintStyle.Fill,
            Color = SKColors.White,
        };

        canvas.DrawRect(rect, paint);

        paint.Color = SKColors.Black;

        // Draw the edges
        for (var i = 0; i < vectors.Count - 1; i++)
        {
            var x1 = vectors[i].X;
            var y1 = vectors[i].Y;
            var x2 = vectors[i + 1].X;
            var y2 = vectors[i + 1].Y;

            canvas.DrawLine(new SKPoint(x1, y1), new SKPoint(x2, y2), paint);
        }

        return bitmap;
    }
}

namespace Algorithms.Other;

/// <summary>
///     Luhn algorithm is a simple
///     checksum formula used to validate
///     a variety of identification numbers,
///     such as credit card numbers.
///     More information on the link:
///     https://en.wikipedia.org/wiki/Luhn_algorithm.
/// </summary>
public static class Luhn
{
    /// <summary>
    ///     Checking the validity of a sequence of numbers.
    /// </summary>
    /// <param name="number">The number that will be checked for validity.</param>
    /// <returns>
    ///     True: Number is valid.
    ///     False: Number isn`t valid.
    /// </returns>
    public static bool Validate(string number) => GetSum(number) % 10 == 0;

    /// <summary>
    ///     This algorithm finds one missing digit.
    ///     In place of the unknown digit, put "x".
    /// </summary>
    /// <param name="number">The number in which to find the missing digit.</param>
    /// <returns>Missing digit.</returns>
    public static int GetLostNum(string number)
    {
        var missingDigitIndex = number.Length - 1 - number.LastIndexOf("x", StringComparison.CurrentCultureIgnoreCase);
        var checkDigit = GetSum(number.Replace("x", "0", StringComparison.CurrentCultureIgnoreCase)) * 9 % 10;

        return missingDigitIndex % 2 == 0
            ? checkDigit
            : Validate(number.Replace("x", (checkDigit / 2).ToString()))
                ? checkDigit / 2
                : (checkDigit + 9) / 2;
    }

    /// <summary>
    ///     Computes the sum found by the Luhn algorithm.
    /// </summary>
    /// <param name="number">The number for which the sum will be calculated.</param>
    /// <returns>Sum.</returns>
    private static int GetSum(string number)
    {
        var sum = 0;
        var span = number.AsSpan();
        for (var i = 0; i < span.Length; i++)
        {
            var c = span[i];
            if (c is < '0' or > '9')
            {
                continue;
            }

            var digit = c - '0';
            digit = (i + span.Length) % 2 == 0 ? 2 * digit : digit;
            if (digit > 9)
            {
                digit -= 9;
            }

            sum += digit;
        }

        return sum;
    }
}

namespace Algorithms.Other;

/// <summary>
/// Almost all real complex decision-making task is described by more than one criterion.
/// Therefore, the methods of multicriteria optimization are important. For a wide range
/// of tasks multicriteria optimization, described by some axioms of "reasonable"
/// behavior in the process of choosing from a set of possible solutions X, each set of
/// selected solutions Sel X should be contained in a set optimal for Pareto.
/// </summary>
public class ParetoOptimization
{
    /// <summary>
    /// Performs decision optimizations by using Paretor's optimization algorithm.
    /// </summary>
    /// <param name="matrix">Contains a collection of the criterias sets.</param>
    /// <returns>An optimized collection of the criterias sets.</returns>
    public List<List<decimal>> Optimize(List<List<decimal>> matrix)
    {
        var optimizedMatrix = new List<List<decimal>>(matrix.Select(i => i));
        int i = 0;
        while (i < optimizedMatrix.Count)
        {
            for (int j = i + 1; j < optimizedMatrix.Count; j++)
            {
                decimal directParwiseDifference = GetMinimalPairwiseDifference(optimizedMatrix[i], optimizedMatrix[j]);
                decimal indirectParwiseDifference = GetMinimalPairwiseDifference(optimizedMatrix[j], optimizedMatrix[i]);
                /*
                 * in case all criteria of one set are larger that the criteria of another, this
                 * decision is not optimal and it has to be removed
                */
                if (directParwiseDifference >= 0 || indirectParwiseDifference >= 0)
                {
                    optimizedMatrix.RemoveAt(directParwiseDifference >= 0 ? j : i);
                    i--;
                    break;
                }
            }

            i++;
        }

        return optimizedMatrix;
    }

    /// <summary>
    /// Calculates the smallest difference between criteria of input decisions.
    /// </summary>
    /// <param name="arr1">Criterias of the first decision.</param>
    /// <param name="arr2">Criterias of the second decision.</param>
    /// <returns>Values that represent the smallest difference between criteria of input decisions.</returns>
    private decimal GetMinimalPairwiseDifference(List<decimal> arr1, List<decimal> arr2)
    {
        decimal min = decimal.MaxValue;
        if (arr1.Count == arr2.Count)
        {
            for (int i = 0; i < arr1.Count; i++)
            {
                decimal difference = arr1[i] - arr2[i];
                if (min > difference)
                {
                    min = difference;
                }
            }
        }

        return min;
    }
}

using Algorithms.Numeric.GreatestCommonDivisor;

namespace Algorithms.Other;

/// <summary>Implementation of the Pollard's rho algorithm.
/// Algorithm for integer factorization.
/// Wiki: https://en.wikipedia.org/wiki/Pollard's_rho_algorithm.
/// </summary>
public static class PollardsRhoFactorizing
{
    public static int Calculate(int number)
    {
        var x = 2;
        var y = 2;
        var d = 1;
        var p = number;
        var i = 0;
        var gcd = new BinaryGreatestCommonDivisorFinder();

        while (d == 1)
        {
            x = Fun_g(x, p);
            y = Fun_g(Fun_g(y, p), p);
            d = gcd.FindGcd(Math.Abs(x - y), p);
            i++;
        }

        return d;
    }

    private static int Fun_g(int x, int p)
    {
        return (x * x + 1) % p;
    }
}

namespace Algorithms.Other;

/// <summary>
///     The RGB color model is an additive color model in which red, green, and
///     blue light are added together in various ways to reproduce a broad array of
///     colors. The name of the model comes from the initials of the three additive
///     primary colors, red, green, and blue. Meanwhile, the HSV representation
///     models how colors appear under light. In it, colors are represented using
///     three components: hue, saturation and (brightness-)value. This class
///     provides methods for converting colors from one representation to the other.
///     (description adapted from https://en.wikipedia.org/wiki/RGB_color_model and
///     https://en.wikipedia.org/wiki/HSL_and_HSV).
/// </summary>
public static class RgbHsvConversion
{
    /// <summary>
    ///     Conversion from the HSV-representation to the RGB-representation.
    /// </summary>
    /// <param name="hue">Hue of the color.</param>
    /// <param name="saturation">Saturation of the color.</param>
    /// <param name="value">Brightness-value of the color.</param>
    /// <returns>The tuple of RGB-components.</returns>
    public static (byte Red, byte Green, byte Blue) HsvToRgb(
        double hue,
        double saturation,
        double value)
    {
        if (hue < 0 || hue > 360)
        {
            throw new ArgumentOutOfRangeException(nameof(hue), $"{nameof(hue)} should be between 0 and 360");
        }

        if (saturation < 0 || saturation > 1)
        {
            throw new ArgumentOutOfRangeException(
                nameof(saturation),
                $"{nameof(saturation)} should be between 0 and 1");
        }

        if (value < 0 || value > 1)
        {
            throw new ArgumentOutOfRangeException(nameof(value), $"{nameof(value)} should be between 0 and 1");
        }

        var chroma = value * saturation;
        var hueSection = hue / 60;
        var secondLargestComponent = chroma * (1 - Math.Abs(hueSection % 2 - 1));
        var matchValue = value - chroma;

        return GetRgbBySection(hueSection, chroma, matchValue, secondLargestComponent);
    }

    /// <summary>
    ///     Conversion from the RGB-representation to the HSV-representation.
    /// </summary>
    /// <param name="red">Red-component of the color.</param>
    /// <param name="green">Green-component of the color.</param>
    /// <param name="blue">Blue-component of the color.</param>
    /// <returns>The tuple of HSV-components.</returns>
    public static (double Hue, double Saturation, double Value) RgbToHsv(
        byte red,
        byte green,
        byte blue)
    {
        var dRed = (double)red / 255;
        var dGreen = (double)green / 255;
        var dBlue = (double)blue / 255;
        var value = Math.Max(Math.Max(dRed, dGreen), dBlue);
        var chroma = value - Math.Min(Math.Min(dRed, dGreen), dBlue);
        var saturation = value.Equals(0) ? 0 : chroma / value;
        double hue;

        if (chroma.Equals(0))
        {
            hue = 0;
        }
        else if (value.Equals(dRed))
        {
            hue = 60 * (0 + (dGreen - dBlue) / chroma);
        }
        else if (value.Equals(dGreen))
        {
            hue = 60 * (2 + (dBlue - dRed) / chroma);
        }
        else
        {
            hue = 60 * (4 + (dRed - dGreen) / chroma);
        }

        hue = (hue + 360) % 360;

        return (hue, saturation, value);
    }

    private static (byte Red, byte Green, byte Blue) GetRgbBySection(
        double hueSection,
        double chroma,
        double matchValue,
        double secondLargestComponent)
    {
        byte red;
        byte green;
        byte blue;

        if (hueSection >= 0 && hueSection <= 1)
        {
            red = ConvertToByte(chroma + matchValue);
            green = ConvertToByte(secondLargestComponent + matchValue);
            blue = ConvertToByte(matchValue);
        }
        else if (hueSection > 1 && hueSection <= 2)
        {
            red = ConvertToByte(secondLargestComponent + matchValue);
            green = ConvertToByte(chroma + matchValue);
            blue = ConvertToByte(matchValue);
        }
        else if (hueSection > 2 && hueSection <= 3)
        {
            red = ConvertToByte(matchValue);
            green = ConvertToByte(chroma + matchValue);
            blue = ConvertToByte(secondLargestComponent + matchValue);
        }
        else if (hueSection > 3 && hueSection <= 4)
        {
            red = ConvertToByte(matchValue);
            green = ConvertToByte(secondLargestComponent + matchValue);
            blue = ConvertToByte(chroma + matchValue);
        }
        else if (hueSection > 4 && hueSection <= 5)
        {
            red = ConvertToByte(secondLargestComponent + matchValue);
            green = ConvertToByte(matchValue);
            blue = ConvertToByte(chroma + matchValue);
        }
        else
        {
            red = ConvertToByte(chroma + matchValue);
            green = ConvertToByte(matchValue);
            blue = ConvertToByte(secondLargestComponent + matchValue);
        }

        return (red, green, blue);
    }

    private static byte ConvertToByte(double input) => (byte)Math.Round(255 * input);
}

namespace Algorithms.Other;

/// <summary>
///     Implements the Sieve of Eratosthenes.
/// </summary>
public class SieveOfEratosthenes
{
    private readonly bool[] primes;

    /// <summary>
    /// Initializes a new instance of the <see cref="SieveOfEratosthenes"/> class.
    /// Uses the Sieve of Eratosthenes to precalculate the primes from 0 up to maximumNumberToCheck.
    /// Requires enough memory to allocate maximumNumberToCheck bytes.
    /// https://en.wikipedia.org/wiki/Sieve_of_Eratosthenes .
    /// </summary>
    /// <param name="maximumNumberToCheck">long which specifies the largest number you wish to know if it is prime.</param>
    public SieveOfEratosthenes(long maximumNumberToCheck)
    {
        primes = new bool[maximumNumberToCheck + 1];

        // initialize primes array
        Array.Fill(this.primes, true, 2, primes.Length - 2);

        for (long i = 2; i * i <= maximumNumberToCheck; i++)
        {
            if (!primes[i])
            {
                continue;
            }

            for (long composite = i * i; composite <= maximumNumberToCheck; composite += i)
            {
                primes[composite] = false;
            }
        }
    }

    /// <summary>
    /// Gets the maximumNumberToCheck the class was instantiated with.
    /// </summary>
    public long MaximumNumber => primes.Length - 1;

    /// <summary>
    /// Returns a boolean indicating whether the number is prime.
    /// </summary>
    /// <param name="numberToCheck">The number you desire to know if it is prime or not.</param>
    /// <returns>A boolean indicating whether the number is prime or not.</returns>
    public bool IsPrime(long numberToCheck) => primes[numberToCheck];

    /// <summary>
    /// Returns an IEnumerable of long primes in asending order.
    /// </summary>
    /// <returns>Primes in ascending order.</returns>
    public IEnumerable<long> GetPrimes()
    {
        for (long i = 2; i < primes.Length; i++)
        {
            if (primes[i])
            {
                yield return i;
            }
        }
    }
}

namespace Algorithms.Other;

public class Triangulator
{
    public (double Latitude, double Longitude) CalculatePosition(List<(double Latitude, double Longitude)> baseLocations, List<double> distances)
    {
        if (baseLocations.Count < 3 || distances.Count < 3)
        {
            throw new ArgumentException("At least three points and corresponding distances are required.");
        }

        // Get the coordinates of the three base stations
        double lat1 = baseLocations[0].Latitude;
        double lon1 = baseLocations[0].Longitude;
        double lat2 = baseLocations[1].Latitude;
        double lon2 = baseLocations[1].Longitude;
        double lat3 = baseLocations[2].Latitude;
        double lon3 = baseLocations[2].Longitude;

        // Convert coordinates to radians
        lat1 = ToRadians(lat1);
        lon1 = ToRadians(lon1);
        lat2 = ToRadians(lat2);
        lon2 = ToRadians(lon2);
        lat3 = ToRadians(lat3);
        lon3 = ToRadians(lon3);

        // Calculate the center point
        double centerLat = (lat1 + lat2 + lat3) / 3;
        double centerLon = (lon1 + lon2 + lon3) / 3;

        // Convert back to degrees
        centerLat = ToDegrees(centerLat);
        centerLon = ToDegrees(centerLon);

        return (centerLat, centerLon);
    }

    private double ToRadians(double degrees)
    {
        return degrees * Math.PI / 180;
    }

    private double ToDegrees(double radians)
    {
        return radians * 180 / Math.PI;
    }
}

namespace Algorithms.Other;

/// <summary>Implementation of Welford's variance algorithm.
/// </summary>
public class WelfordsVariance
{
    /// <summary>
    ///     Mean accumulates the mean of the entire dataset,
    ///     m2 aggregates the squared distance from the mean,
    ///     count aggregates the number of samples seen so far.
    /// </summary>
    private int count;

    public double Count => count;

    private double mean;

    public double Mean => count > 1 ? mean : double.NaN;

    private double m2;

    public double Variance => count > 1 ? m2 / count : double.NaN;

    public double SampleVariance => count > 1 ? m2 / (count - 1) : double.NaN;

    public WelfordsVariance()
    {
        count = 0;
        mean = 0;
    }

    public WelfordsVariance(double[] values)
    {
        count = 0;
        mean = 0;
        AddRange(values);
    }

    public void AddValue(double newValue)
    {
        count++;
        AddValueToDataset(newValue);
    }

    public void AddRange(double[] values)
    {
        var length = values.Length;
        for (var i = 1; i <= length; i++)
        {
            count++;
            AddValueToDataset(values[i - 1]);
        }
    }

    private void AddValueToDataset(double newValue)
    {
        var delta1 = newValue - mean;
        var newMean = mean + delta1 / count;

        var delta2 = newValue - newMean;
        m2 += delta1 * delta2;

        mean = newMean;
    }
}

namespace Algorithms.Problems.DynamicProgramming.CoinChange;

public static class DynamicCoinChangeSolver
{
    /// <summary>
    /// Generates an array of changes for current coin.
    /// For instance, having coin C = 6 and array A = [1,3,4] it returns an array R = [2,3,5].
    /// Because, 6 - 4 = 2, 6 - 3 = 3, 6 - 1 = 5.
    /// </summary>
    /// <param name="coin">The value of the coin to be exchanged.</param>
    /// <param name="coins">An array of available coins.</param>
    /// <returns>Array of changes of current coins by available coins.</returns>
    public static int[] GenerateSingleCoinChanges(int coin, int[] coins)
    {
        ValidateCoin(coin);
        ValidateCoinsArray(coins);

        var coinsArrayCopy = new int[coins.Length];

        Array.Copy(coins, coinsArrayCopy, coins.Length);
        Array.Sort(coinsArrayCopy);
        Array.Reverse(coinsArrayCopy);

        List<int> list = [];

        foreach (var item in coinsArrayCopy)
        {
            if (item > coin)
            {
                continue;
            }

            var difference = coin - item;

            list.Add(difference);
        }

        var result = list.ToArray();

        return result;
    }

    /// <summary>
    /// Given a positive integer N, such as coin.
    /// Generates a change dictionary for all values [1,N].
    /// Used in so-called backward induction in search of the minimum exchange.
    /// </summary>
    /// <param name="coin">The value of coin.</param>
    /// <param name="coins">Array of available coins.</param>
    /// <returns>Change dictionary for all values [1,N], where N is the coin.</returns>
    public static Dictionary<int, int[]> GenerateChangesDictionary(int coin, int[] coins)
    {
        Dictionary<int, int[]> dict = [];
        var currentCoin = 1;

        while (currentCoin <= coin)
        {
            var changeArray = GenerateSingleCoinChanges(currentCoin, coins);
            dict[currentCoin] = changeArray;
            currentCoin++;
        }

        return dict;
    }

    /// <summary>
    /// Gets a next coin value, such that changes array contains the minimal change overall possible changes.
    /// For example, having coin N = 6 and A = [1,3,4] coins array.
    /// The minimum next coin for 6 will be 3, because changes of 3 by A = [1,3,4] contains 0, the minimal change.
    /// </summary>
    /// <param name="coin">Coin to be exchanged.</param>
    /// <param name="exchanges">Dictionary of exchanges for [1, coin].</param>
    /// <returns>Index of the next coin with minimal exchange.</returns>
    public static int GetMinimalNextCoin(int coin, Dictionary<int, int[]> exchanges)
    {
        var nextCoin = int.MaxValue;
        var minChange = int.MaxValue;

        var coinChanges = exchanges[coin];

        foreach (var change in coinChanges)
        {
            if (change == 0)
            {
                return 0;
            }

            var currentChange = exchanges[change];
            var min = currentChange.Min();

            var minIsLesser = min < minChange;

            if (minIsLesser)
            {
                nextCoin = change;
                minChange = min;
            }
        }

        return nextCoin;
    }

    /// <summary>
    /// Performs a coin change such that an amount of coins is minimal.
    /// </summary>
    /// <param name="coin">The value of coin to be exchanged.</param>
    /// <param name="coins">An array of available coins.</param>
    /// <returns>Array of exchanges.</returns>
    public static int[] MakeCoinChangeDynamic(int coin, int[] coins)
    {
        var changesTable = GenerateChangesDictionary(coin, coins);
        var list = new List<int>();

        var currentCoin = coin;
        var nextCoin = int.MaxValue;

        while (nextCoin != 0)
        {
            nextCoin = GetMinimalNextCoin(currentCoin, changesTable);
            var difference = currentCoin - nextCoin;
            list.Add(difference);
            currentCoin = nextCoin;
        }

        var result = list.ToArray();

        return result;
    }

    private static void ValidateCoin(int coin)
    {
        if (coin <= 0)
        {
            throw new InvalidOperationException($"The coin cannot be lesser or equal to zero {nameof(coin)}.");
        }
    }

    private static void ValidateCoinsArray(int[] coinsArray)
    {
        var coinsAsArray = coinsArray.ToArray();

        if (coinsAsArray.Length == 0)
        {
            throw new InvalidOperationException($"Coins array cannot be empty {nameof(coinsAsArray)}.");
        }

        var coinsContainOne = coinsAsArray.Any(x => x == 1);

        if (!coinsContainOne)
        {
            throw new InvalidOperationException($"Coins array must contain coin 1 {nameof(coinsAsArray)}.");
        }

        var containsNonPositive = coinsAsArray.Any(x => x <= 0);

        if (containsNonPositive)
        {
            throw new InvalidOperationException(
                $"{nameof(coinsAsArray)} cannot contain numbers less than or equal to zero");
        }

        var containsDuplicates = coinsAsArray.GroupBy(x => x).Any(g => g.Count() > 1);

        if (containsDuplicates)
        {
            throw new InvalidOperationException($"Coins array cannot contain duplicates {nameof(coinsAsArray)}.");
        }
    }
}

namespace Algorithms.Problems.DynamicProgramming;

/// <summary>
///     <para>
///         Levenshtein distance between two words is the minimum number of single-character edits (insertions, deletions or substitutions) required to change one word into the other.
///     </para>
///     <para>
///         Wikipedia: https://en.wikipedia.org/wiki/Levenshtein_distance.
///     </para>
/// </summary>
public static class LevenshteinDistance
{
    /// <summary>
    ///     Calculates Levenshtein distance.
    ///     Time and space complexity is O(ab) where a and b are the lengths of the source and target strings.
    /// </summary>
    /// <param name="source">Source string.</param>
    /// <param name="target">Target string.</param>
    /// <returns>Levenshtein distance between source and target strings.</returns>
    public static int Calculate(string source, string target)
    {
        var distances = new int[source.Length + 1, target.Length + 1];

        for (var i = 0; i <= source.Length; i++)
        {
            distances[i, 0] = i;
        }

        for (var i = 0; i <= target.Length; i++)
        {
            distances[0, i] = i;
        }

        for (var i = 1; i <= source.Length; i++)
        {
            for (var j = 1; j <= target.Length; j++)
            {
                var substitionCost = source[i - 1] == target[j - 1] ? 0 : 1;
                distances[i, j] = Math.Min(distances[i - 1, j] + 1, Math.Min(distances[i, j - 1] + 1, distances[i - 1, j - 1] + substitionCost));
            }
        }

        return distances[source.Length, target.Length];
    }
}

namespace Algorithms.Problems.GraphColoring;

/// <summary>
/// Solves the Graph Coloring Problem using backtracking to assign colors to graph vertices
/// such that no two adjacent vertices share the same color.
/// </summary>
/// <remarks>
/// <para>
/// The Graph Coloring Problem is an NP-complete problem that aims to color the vertices
/// of a graph with the minimum number of colors such that no two adjacent vertices have
/// the same color. This implementation uses a backtracking algorithm to find a valid coloring
/// given a specific number of colors.
/// </para>
/// <para>
/// The algorithm attempts to assign colors to vertices one by one. If a color assignment
/// leads to a conflict, it backtracks and tries a different color. If no valid coloring
/// exists with the given number of colors, an exception is thrown.
/// </para>
/// <para>
/// <b>Complexity:</b> The worst-case time complexity is O(k^n) where n is the number of
/// vertices and k is the number of colors. This is an exponential algorithm suitable for
/// small to medium-sized graphs or graphs with special structures.
/// </para>
/// <para>
/// <b>Applications:</b> Graph coloring has numerous practical applications including:
/// register allocation in compilers, scheduling problems, frequency assignment in mobile networks,
/// and solving Sudoku puzzles.
/// </para>
/// <para>
/// For more information, see:
/// <see href="https://en.wikipedia.org/wiki/Graph_coloring">Graph Coloring on Wikipedia</see>.
/// </para>
/// </remarks>
public sealed class GraphColoringSolver
{
    /// <summary>
    /// Attempts to color a graph with the specified number of colors.
    /// </summary>
    /// <param name="adjacencyMatrix">
    /// A square boolean matrix representing the graph where <c>adjacencyMatrix[i, j]</c>
    /// is <c>true</c> if there is an edge between vertex <c>i</c> and vertex <c>j</c>.
    /// The matrix must be symmetric for undirected graphs.
    /// </param>
    /// <param name="numColors">The number of colors to use for coloring. Must be positive.</param>
    /// <returns>
    /// An array where each element represents the color assigned to the corresponding vertex
    /// (0-indexed colors from 0 to <paramref name="numColors"/> - 1).
    /// </returns>
    /// <exception cref="ArgumentNullException">
    /// Thrown when <paramref name="adjacencyMatrix"/> is <c>null</c>.
    /// </exception>
    /// <exception cref="ArgumentException">
    /// Thrown when the adjacency matrix is not square, when <paramref name="numColors"/> is non-positive,
    /// or when no valid coloring exists with the given number of colors.
    /// </exception>
    /// <remarks>
    /// <para>
    /// This method finds the first valid coloring it encounters. Multiple valid colorings
    /// may exist for a given graph, but only one is returned.
    /// </para>
    /// <para>
    /// <b>Example:</b> For a triangle graph (3 vertices, all connected), at least 3 colors
    /// are required. Calling this method with <c>numColors = 2</c> will throw an exception,
    /// while <c>numColors = 3</c> will return a valid coloring such as <c>[0, 1, 2]</c>.
    /// </para>
    /// </remarks>
    public int[] ColorGraph(bool[,] adjacencyMatrix, int numColors)
    {
        if (adjacencyMatrix is null)
        {
            throw new ArgumentNullException(nameof(adjacencyMatrix));
        }

        var numVertices = adjacencyMatrix.GetLength(0);

        if (numVertices != adjacencyMatrix.GetLength(1))
        {
            throw new ArgumentException("Adjacency matrix must be square.", nameof(adjacencyMatrix));
        }

        if (numColors <= 0)
        {
            throw new ArgumentException("Number of colors must be positive.", nameof(numColors));
        }

        // Handle empty graph
        if (numVertices == 0)
        {
            return Array.Empty<int>();
        }

        var colors = new int[numVertices];

        // Initialize all vertices as uncolored (-1)
        Array.Fill(colors, -1);

        if (!ColorVertex(adjacencyMatrix, colors, 0, numColors))
        {
            throw new ArgumentException(
                $"Graph cannot be colored with {numColors} color(s). " +
                $"A larger number of colors may be required.");
        }

        return colors;
    }

    /// <summary>
    /// Recursively attempts to color vertices using backtracking.
    /// </summary>
    /// <param name="adjacencyMatrix">The graph adjacency matrix.</param>
    /// <param name="colors">Current color assignment for each vertex.</param>
    /// <param name="vertex">The current vertex to color.</param>
    /// <param name="numColors">The number of available colors.</param>
    /// <returns><c>true</c> if a valid coloring is found; otherwise, <c>false</c>.</returns>
    /// <remarks>
    /// This method tries each available color for the current vertex. If a color is valid
    /// (doesn't conflict with adjacent vertices), it proceeds to color the next vertex.
    /// If no valid color is found, it backtracks.
    /// </remarks>
    private bool ColorVertex(bool[,] adjacencyMatrix, int[] colors, int vertex, int numColors)
    {
        var numVertices = adjacencyMatrix.GetLength(0);

        // Base case: all vertices are colored
        if (vertex == numVertices)
        {
            return true;
        }

        // Try each color for the current vertex
        for (var color = 0; color < numColors; color++)
        {
            if (IsSafeToColor(adjacencyMatrix, colors, vertex, color))
            {
                colors[vertex] = color;

                // Recursively color the next vertex
                if (ColorVertex(adjacencyMatrix, colors, vertex + 1, numColors))
                {
                    return true;
                }

                // Backtrack if the current color assignment doesn't lead to a solution
                colors[vertex] = -1;
            }
        }

        return false;
    }

    /// <summary>
    /// Checks whether it is safe to assign a color to a vertex.
    /// </summary>
    /// <param name="adjacencyMatrix">The graph adjacency matrix.</param>
    /// <param name="colors">Current color assignment for each vertex.</param>
    /// <param name="vertex">The vertex to check.</param>
    /// <param name="color">The color to assign.</param>
    /// <returns>
    /// <c>true</c> if the color can be safely assigned (no adjacent vertex has this color);
    /// otherwise, <c>false</c>.
    /// </returns>
    /// <remarks>
    /// A color is safe to assign if none of the already-colored adjacent vertices
    /// have the same color.
    /// </remarks>
    private bool IsSafeToColor(bool[,] adjacencyMatrix, int[] colors, int vertex, int color)
    {
        var numVertices = adjacencyMatrix.GetLength(0);

        for (var i = 0; i < numVertices; i++)
        {
            // Check if vertex i is adjacent to the current vertex and has the same color
            if (adjacencyMatrix[vertex, i] && colors[i] == color)
            {
                return false;
            }
        }

        return true;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace Algorithms.Problems.JobScheduling;

/// <summary>
/// Implements the greedy algorithm for Interval Scheduling.
/// Finds the maximum set of non-overlapping jobs.
/// </summary>
public static class IntervalSchedulingSolver
{
    /// <summary>
    /// Returns the maximal set of non-overlapping jobs.
    /// </summary>
    /// <param name="jobs">List of jobs to schedule.</param>
    /// <returns>List of selected jobs (maximal set).</returns>
    public static List<Job> Schedule(IEnumerable<Job> jobs)
    {
        if (jobs == null)
        {
            throw new ArgumentNullException(nameof(jobs));
        }

        // Sort jobs by their end time (earliest finish first)
        var sortedJobs = jobs.OrderBy(j => j.End).ToList();
        var result = new List<Job>();
        int lastEnd = int.MinValue;

        foreach (var job in sortedJobs)
        {
            // If the job starts after the last selected job ends, select it
            if (job.Start >= lastEnd)
            {
                result.Add(job);
                lastEnd = job.End;
            }
        }

        return result;
    }
}

