public class MatrixExtensionsTests
{
    private static readonly object[] MatrixMultiplyTestCases =
    [
        new object[]
        {
            new double[,] { { 2, 2, -1 }, { 0, -2, -1 }, { 0, 0, 5 } },
            new double[,] { { 2 }, { 2 }, { 3 } },
